def listorfs(x, strand):
    out=[]
    for f in range(3):
        t=translate(x,f)
        st=0
        for idx,aa in enumerate(t):
            if aa=='*':
                if idx-st>=40:
                    # nucleotide coords on x (0-based)
                    a=st*3+f; b=idx*3+f
                    if strand=='+':
                        coords=(a+1, b+2)  # stop codon occupies b+1..b+3 -> 1-based
                    else:
                        coords=(n-(b+2)+1, n-a)
                    out.append((coords, idx-st, t[st:idx], strand, f))
                st=idx+1
        if len(t)-st>=40:
            a=st*3+f; b=len(t)*3+f
            if strand=='+': coords=(a+1, b)
            else: coords=(n-b+1, n-a)
            out.append((coords, len(t)-st, t[st:], strand, f))
    return out

